import * as THREE from 'three';
import { OBJExporter } from 'three/examples/jsm/exporters/OBJExporter.js';
import { createScene } from './data/object.js';
import * as fs from 'fs';
import * as path from 'path';

// Create the scene
const scene = createScene();

// Create a wrapper group for Blender Z-up conversion
// Apply -90 degrees rotation around X-axis to convert from Y-up to Z-up
const blenderConversionGroup = new THREE.Group();
blenderConversionGroup.rotation.x = -Math.PI / 2; // -90 degrees in radians
blenderConversionGroup.add(scene);

// Update all matrices to apply transformations
blenderConversionGroup.updateMatrixWorld(true);

// Function to expand InstancedMesh into individual meshes
function expandInstancedMeshes(object) {
  const meshesToAdd = [];
  const meshesToRemove = [];

  object.traverse((child) => {
    if (child instanceof THREE.InstancedMesh) {
      meshesToRemove.push({ parent: child.parent, mesh: child });

      const dummy = new THREE.Object3D();
      for (let i = 0; i < child.count; i++) {
        child.getMatrixAt(i, dummy.matrix);
        dummy.matrix.decompose(dummy.position, dummy.quaternion, dummy.scale);

        const instanceMesh = new THREE.Mesh(child.geometry, child.material);
        instanceMesh.position.copy(dummy.position);
        instanceMesh.quaternion.copy(dummy.quaternion);
        instanceMesh.scale.copy(dummy.scale);
        instanceMesh.name = `${child.name}_instance_${i}`;

        meshesToAdd.push({ parent: child.parent, mesh: instanceMesh });
      }
    }
  });

  // Remove instanced meshes and add individual meshes
  meshesToRemove.forEach(({ parent, mesh }) => {
    if (parent) parent.remove(mesh);
  });

  meshesToAdd.forEach(({ parent, mesh }) => {
    if (parent) parent.add(mesh);
  });
}

// Expand instanced meshes before export
expandInstancedMeshes(blenderConversionGroup);

// Update matrices again after expanding instances
blenderConversionGroup.updateMatrixWorld(true);

// Create OBJ exporter and export
const exporter = new OBJExporter();
const objContent = exporter.parse(blenderConversionGroup);

// Ensure output directory exists
const outputDir = '/root/output';
if (!fs.existsSync(outputDir)) {
  fs.mkdirSync(outputDir, { recursive: true });
}

// Write OBJ file
const outputPath = path.join(outputDir, 'object.obj');
fs.writeFileSync(outputPath, objContent);

console.log(`✓ Successfully exported to ${outputPath}`);
console.log(`✓ Applied -90° X-rotation for Blender Z-up coordinate system`);
console.log(`✓ Expanded instanced meshes to individual meshes`);
console.log(`✓ All original 3D positions preserved`);

